module FragmentAssembly(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input [15:0] k_values [0:7],\n    input [3:0] n,\n    output reg [31:0] result,\n    output reg done\n);\n    // Precomputed distance to root for k! (k from 0 to 16)\n    localparam [31:0] dist_to_root [0:16] = '{32'd0, 32'd0, 32'd1, 32'd2, 32'd4, 32'd5, 32'd7, 32'd8, 32'd11, 32'd13, 32'd15, 32'd16, 32'd19, 32'd20, 32'd22, 32'd24, 32'd28};\n\n    // State declarations\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] COUNT = 3'd1;\n    localparam [2:0] COMPUTE_DIST = 3'd2;\n    localparam [2:0] FIND_BRANCH = 3'd3;\n    localparam [2:0] MOVING = 3'd4;\n    localparam [2:0] DONE_STATE = 3'd5;\n\n    reg [2:0] state, next_state;\n    reg [7:0] count [0:16];  // Histogram for k values\n    reg [3:0] freq [0:5];    // Histogram for prime branches (primes: 2,3,5,7,11,13)\n    reg [4:0] i, k;          // Loop counters\n    reg [31:0] initial_sum;  // Initial distance sum\n    reg [31:0] best_delta;   // Best delta found\n    reg [2:0] best_prime;    // Prime branch with best delta\n    reg found_move;\n\n    // Main state machine\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            for (i = 0; i < 17; i = i + 1) begin\n                count[i] <= 8'd0;\n            end\n            for (i = 0; i < 6; i = i + 1) begin\n                freq[i] <= 4'd0;\n            end\n            initial_sum <= 32'd0;\n            best_delta <= 32'd0;\n            best_prime <= 3'd0;\n            found_move <= 1'b0;\n            i <= 5'd0;\n            k <= 5'd0;\n        end else begin\n            done <= 1'b0;  // Default done to 0\n            case (state)\n                IDLE: begin\n                    if (start) begin\n                        state <= COUNT;\n                    end\n                end\n\n                COUNT: begin\n                    if (i < 16) begin\n                        if (i < n) begin\n                            k = k_values[i];\n                            if (k <= 16) begin\n                                count[k] <= count[k] + 8'd1;\n                            end\n                            i <= i + 5'd1;\n                        end else begin\n                            state <= COMPUTE_DIST;\n                            i <= 5'd0;\n                            k <= 5'd2;\n                        end\n                    end else begin\n                        state <= COMPUTE_DIST;\n                        i <= 5'd0;\n                        k <= 5'd2;\n                    end\n                end\n\n                COMPUTE_DIST: begin\n                    if (k <= 16) begin\n                        initial_sum <= initial_sum + (count[k] * dist_to_root[k]);\n                        k <= k + 5'd1;\n                    end else begin\n                        if (count[1] > (n >> 1)) begin\n                            result <= 32'd0;\n                            state <= DONE_STATE;\n                        end else begin\n                            state <= FIND_BRANCH;\n                            i <= 5'd0;  // Reset i for prime loop\n                        end\n                    end\n                end\n\n                FIND_BRANCH: begin\n                    // For each prime index i: calc freq[i]\n                    if (i < 6) begin\n                        case (i)\n                            0: freq[0] <= count[2] + count[3] + count[4] + count[5] + count[6] + count[7] + count[8] + count[9] + count[10] + count[11] + count[12] + count[13] + count[14] + count[15] + count[16];\n                            1: freq[1] <= count[3] + count[5] + count[7] + count[9] + count[11] + count[13] + count[15];\n                            2: freq[2] <= count[5] + count[7] + count[11] + count[13];\n                            3: freq[3] <= count[7] + count[14];\n                            4: freq[4] <= count[11];\n                            5: freq[5] <= count[13];\n                        endcase\n                        i <= i + 5'd1;\n                    end else begin\n                        // Analyze freq after all update\n                        state <= MOVING;\n                        i <= 5'd0;\n                        best_prime <= 3'd0;\n                        best_delta <= 32'd0;\n                        found_move <= 1'b0;\n                    end\n                end\n\n                MOVING: begin\n                    if (i < 6) begin\n                        if (freq[i] > (n >> 1)) begin\n                            if (best_delta < (freq[i] - (n - freq[i]))) begin\n                                best_delta <= (freq[i] - (n - freq[i]));\n                                best_prime <= i[2:0];\n                                found_move <= 1'b1;\n                            end\n                        end\n                        i <= i + 5'd1;\n                    end else begin\n                        if (found_move) begin\n                            result <= initial_sum - best_delta;\n                        end else begin\n                            result <= initial_sum;\n                        end\n                        state <= DONE_STATE;\n                    end\n                end\n\n                DONE_STATE: begin\n                    done <= 1'b1;\n                    state <= IDLE;  // Return to IDLE after completion\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule